head.script:
(function(){
    var t = localStorage.getItem('dw-theme') || 'light';
    document.documentElement.setAttribute('data-theme', t);
    var l = localStorage.getItem('recycle_wms_lang');
    if (l === 'ar') {
        document.documentElement.setAttribute('dir', 'rtl');
        document.documentElement.setAttribute('lang', 'ar');
    }
})();

body.script:
// ── Theme ──────────────────────────────────────────
function dwUpdateThemeBtn() {
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    var btn = document.getElementById('dw-theme-btn');
    if (btn) btn.textContent = dark ? '☀️' : '🌙';
}
function dwToggleTheme() {
    var current = document.documentElement.getAttribute('data-theme');
    var next = current === 'dark' ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('dw-theme', next);
    dwUpdateThemeBtn();
}
dwUpdateThemeBtn();

// ── Instant navbar active state on click ──────────
// The clicked item lights up green immediately (before
// the new page loads) and stays lit — desktop + drawer.
document.addEventListener('click', function (e) {
    var link = e.target.closest ? e.target.closest('.dw-link') : null;
    if (!link || !link.getAttribute('href')) return;
    var all = document.querySelectorAll('.dw-link');
    for (var i = 0; i < all.length; i++) all[i].classList.remove('active');
    link.classList.add('active');
});

// ── Mobile nav ─────────────────────────────────────
function dwToggleNav() {
    var drawer = document.getElementById('dw-nav-drawer');
    if (drawer) drawer.classList.toggle('open');
}
// Close on outside click
document.addEventListener('click', function(e) {
    var ham = document.getElementById('dw-ham');
    var drawer = document.getElementById('dw-nav-drawer');
    if (drawer && !drawer.contains(e.target) && ham && !ham.contains(e.target)) {
        drawer.classList.remove('open');
    }
});

// ── Run i18n after page is fully loaded ──
if (typeof dwApplyTranslations === 'function') {
    if (document.readyState === 'complete') {
        dwApplyTranslations();
    } else {
        window.addEventListener('load', dwApplyTranslations);
    }
}

div.script:
var dwJobType = 'all';
function dwJobTab(btn) {
    dwJobType = btn.getAttribute('data-type');
    var tabs = document.querySelectorAll('.dw-jobs-tab');
    for (var i = 0; i < tabs.length; i++) tabs[i].classList.remove('active');
    btn.classList.add('active');
    dwFilterJobs();
}
function dwFilterJobs() {
    var q = (document.getElementById('dwJobSearch').value || '').toLowerCase().trim();
    var rows = document.querySelectorAll('#dwJobsList .dw-job-row');
    var visible = 0;
    for (var i = 0; i < rows.length; i++) {
        var r = rows[i];
        var okType = dwJobType === 'all' || r.getAttribute('data-type') === dwJobType;
        var okText = !q || (r.getAttribute('data-name') || '').indexOf(q) !== -1;
        var show = okType && okText;
        r.style.display = show ? '' : 'none';
        if (show) visible++;
    }
    var empty = document.getElementById('dwJobsEmpty');
    if (empty) empty.style.display = visible ? 'none' : 'block';
}

function dwOpenPwd() {
    document.getElementById('dwPwdModal').style.display = 'flex';
}
function dwClosePwd() {
    document.getElementById('dwPwdModal').style.display = 'none';
}
function dwOpenEditProfile() {
    document.getElementById('dwEditProfileModal').style.display = 'flex';
}
function dwCloseEditProfile() {
    document.getElementById('dwEditProfileModal').style.display = 'none';
}
// Auto-open the modal when the server returned a password error.
dwOpenPwd();
// Auto-open the modal when the server returned a profile edit error.
dwOpenEditProfile();
// Set language for hidden inputs (from JS language toggle)

var dwLangInputs = document.querySelectorAll('.dw_lang_input');
for (var d = 0; d < dwLangInputs.length; d++) {
    dwLangInputs[d].value = (typeof dwGetLang === 'function') ? dwGetLang() : 'en';
}

template.script:
function dwFloatSync() {
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    var tb = document.getElementById('dw-float-theme');
    if (tb) tb.textContent = dark ? '☀️' : '🌙';
    var isAr = (localStorage.getItem('recycle_wms_lang') === 'ar');
    var lb = document.getElementById('dw-float-lang');
    if (lb) lb.textContent = isAr ? 'EN' : 'AR';
}
function dwFloatToggleTheme() {
    var next = document.documentElement.getAttribute('data-theme') === 'dark'
        ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('dw-theme', next);
    dwFloatSync();
}
function dwFloatToggleLang() {
    var next = (localStorage.getItem('recycle_wms_lang') === 'ar') ? 'en' : 'ar';
    if (typeof dwSetLang === 'function') {
        dwSetLang(next);
    } else {
        localStorage.setItem('recycle_wms_lang', next);
        document.documentElement.setAttribute('dir', next === 'ar' ? 'rtl' : 'ltr');
        document.documentElement.setAttribute('lang', next);
    }
    dwFloatSync();
}
dwFloatSync();

