template.script:
function dwTogglePass(id, eyeId) {
    var inp = document.getElementById(id);
    var eye = document.getElementById(eyeId);
    if (inp.type === 'password') {
        inp.type = 'text'; eye.textContent = '🙈';
    } else {
        inp.type = 'password'; eye.textContent = '👁';
    }
}

