template.script:
(function() {
    var inputs = [1,2,3,4,5,6].map(function(i){
        return document.getElementById('otp-' + i);
    });
    inputs.forEach(function(inp, idx) {
        inp.addEventListener('keydown', function(e) {
            if (!/[0-9]/.test(e.key) &&
                !['Backspace','Delete','Tab','ArrowLeft','ArrowRight'].includes(e.key)) {
                e.preventDefault();
            }
        });
        inp.addEventListener('input', function() {
            this.value = this.value.replace(/[^0-9]/g, '');
            if (this.value.length === 1 && idx < 5) {
                inputs[idx + 1].focus();
            }
            var code = inputs.map(function(x){ return x.value; }).join('');
            if (code.length === 6) {
                setTimeout(function(){
                    document.getElementById('otp-form').submit();
                }, 120);
            }
        });
        inp.addEventListener('keydown', function(e) {
            if (e.key === 'Backspace' && !this.value && idx > 0) {
                inputs[idx - 1].focus();
            }
        });
    });
    inputs[0].addEventListener('paste', function(e) {
        e.preventDefault();
        var text = (e.clipboardData || window.clipboardData)
                    .getData('text').replace(/[^0-9]/g, '').slice(0, 6);
        text.split('').forEach(function(ch, i) {
            if (inputs[i]) inputs[i].value = ch;
        });
        if (text.length === 6) {
            setTimeout(function(){
                document.getElementById('otp-form').submit();
            }, 120);
        } else if (inputs[text.length]) {
            inputs[text.length].focus();
        }
    });
    inputs[0].focus();
    var secs = 600;
    var el = document.getElementById('otp-countdown');
    var timer = setInterval(function() {
        secs--;
        if (secs <= 0) {
            clearInterval(timer);
            if (el) el.textContent = 'Expired';
            return;
        }
        var m = Math.floor(secs / 60);
        var s = secs % 60;
        if (el) el.textContent =
            (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
    }, 1000);
})();
